"""Materialize the continuing analyst's focal judgments, exact anchors and case maps.

This script reproduces structured records; it does not run or evaluate a model.
"""
from pathlib import Path
import json, csv, hashlib, re

ROOT=Path(__file__).resolve().parents[1]
packets={p.stem:json.loads(p.read_text()) for p in (ROOT/'sources/packets').glob('E??.json')}
sources={e['source_id']:e for p in packets.values() for e in p['entries']+p['supplemental_entries']}
claims=[]
def anchor(eid,suffix,quote=None):
    sid=eid+':'+suffix; text=sources[sid]['text']; quote=text if quote is None else quote
    start=text.index(quote)
    return {'source_id':sid,'span':{'start':start,'end':start+len(quote),'quote':quote}}
def claim(eid,label,text,status,refs,limit):
    evidence=[anchor(eid,*r) for r in refs]
    layer=max((sources[r['source_id']]['layer'] for r in evidence),key='DTI'.index)
    claims.append(dict(claim_id=eid+'-'+label,episode_id=eid,claim=text,assessment=status,evidence=evidence,assessment_available_at=layer,limits_and_alternatives=limit))

claim('E01','C1','Merged guidance asks contributors to reuse the existing PR for the same change.','supported',[('doc_head','Please refrain from creating several pull requests for the same change.'),('outcome','"recorded_merged": true')],'The scope is duplicate PRs for one change, not several unrelated contributions. Integration is documented; universal compliance is not.')
claim('E01','C2','The added guidance offers allowing maintainer edits and asking for help as an alternative when Git workflows cause problems.','supported',[('doc_head','If you have problems with squashing (or other workflows with `git`), you can\nalternatively enable "Allow edits from maintainers" in the right GitHub\nsidebar and ask for help in the pull request.')],'Optional workflow support does not impose a duty to grant access.')
claim('E01','C3','The discussion gives an assistance and workload rationale for the help option.','attributed',[('review_comments:2',"Well, not in general, but we want to encourage it for people that don't know how to use git.")],'Attributed rationale is not a measured reduction in tutoring costs.')
claim('E01','C4','This change prohibits a contributor from having several unrelated PRs open.','contradicted',[('doc_head','for the same change.')],'The qualifier defeats this broad reading; no claim is made about other unseen rules.')

claim('E02','C1','Merged guidance permits maintainers to close trivial PRs or refactoring PRs with no clear benefit immediately.','supported',[('doc_head','Trivial pull requests or pull requests that refactor the code with no clear\nbenefits may be immediately closed by the maintainers to reduce unnecessary\nworkload on reviewing.'),('outcome','"recorded_merged": true')],'May grants discretion; the text does not require closure or evidence an actual application in this PR.')
claim('E02','C2','Merged guidance advises new contributors against submitting refactoring PRs.','supported',[('doc_head','Pull requests that refactor the code should not be made by new contributors.'),('outcome','"recorded_merged": true')],'Advisory should not is coded as recommendation; a stronger prohibition reading needs additional authority and usage evidence.')
claim('E02','C3','A reviewer separately proposed closure when a refactoring PR attracts no reviewer; that wording is absent from the supplied final guide.','supported',[('review_comments:2',"Any refactoring pull request may be closed when it doesn't attract anyone willing to review."),('doc_head','Trivial pull requests or pull requests that refactor the code with no clear\nbenefits may be immediately closed by the maintainers')],'Absence was checked against the complete head file. A proposal in a merged thread is not automatically adopted.')
claim('E02','C4','This PR demonstrates enforcement of the newly stated closure permission against an author.','unresolved',[('body','This PR would prepare for possible direct PR closing.'),('outcome','"recorded_merged": true')],'The observed event revises guidance; an enforcement episode would need a separately linked application.')

claim('E03','C1','The unmerged developer-notes proposal distinguishes conflict-driven rebasing from disruptive rebasing without conflicts and preserves within-branch fixups.','supported',[('doc_developer_head','When the master development branch develops conflicts with your pull request,\nyou need to rebase it.'),('doc_developer_head','Note that when there are no conflicts at all, however, rebasing should be\navoided, as it can be disruptive to reviewers. (The `git rebase` command may\nstill be useful for fixups or reorganization *within* your branch; that\'s\nusually ok to do.)'),('outcome','"recorded_merged": false')],'This is proposed wording in doc/developer-notes.md, not adopted CONTRIBUTING guidance.')
claim('E03','C2','A suggestion to document DrahtBot warnings drew an objection about project and platform boundaries.','supported',[('comments:0','Maybe it\'s worth pointing it out that drahtbot will give a warning if a rebase is required.'),('comments:3',"I don't agree with your suggestion because @DrahtBot is not part of the project and integrates with GitHub.")],'The participant assertion is not an independently verified organizational status of the bot.')
claim('E03','C3','The record contains qualified support and a request to answer feedback despite eventual closure without merge.','supported',[('comments:8',"author doesn't want to address nits so ACKing."),('comments:7',"it still would be nice if you replied to the feedback to say why it doesn't apply."),('outcome','"recorded_merged": false')],'Support, feedback and closure must remain separate events; positive review did not by itself establish integration.')
claim('E03','C4','Closure establishes project-wide rejection of rebasing guidance or of the bot.','unresolved',[('comments:8','Willing to review a follow up PR that picks up the nits.'),('outcome','"recorded_merged": false')],'The packet does not establish a project-wide vote, unanimous judgment or a uniquely identified cause of closure.')

claim('E04','C1','Standing guidance expects replies to review comments before merge, allows reasoned disagreement, and permits closure for inactive outstanding feedback.','supported',[('doc_before','You are expected to reply to any review comments before your pull request is\nmerged. You may update the code or reject the feedback if you do not agree with\nit, but you should express so in a reply. If there is outstanding feedback and\nyou are not actively working on it, your pull request may be closed.')],'The documented duty is to respond, not to accept every reviewer demand.')
claim('E04','C2','maflcko explicitly links closure to alleged failures to prepare, explain and respond under the contribution guidelines.','attributed',[('comments:5',"You created a one-line patch in 4 commits, ignored previous discussions, ignored two review comments, with no apparent progress in about a month. I closed this for now, because it can't be merged according to the guidelines."),('outcome','"recorded_merged": false'),('doc_before','your pull request may be closed.')],'This is an attributable enforcement claim with a provision, alleged trigger, actor and consequence. It does not independently establish every allegation or exclusive causation.')
claim('E04','C3','The author disputes the technical criticism while agreeing to continue discussion in the issue.','supported',[('comments:4',"The first sentence in your comment only makes sense in a vacuum. The standard is a thing. I agree with the second part. Let's.")],'Agreement to redirect discussion does not acknowledge all procedural allegations.')
claim('E04','C4','The closure was caused solely by procedural noncompliance, independently of technical disagreement.','unresolved',[('comments:4',"It doesn't \"seem[sic]\" to fix the issue?"),('comments:5',"I closed this for now, because it can't be merged according to the guidelines.")],'Participant reasoning supports a procedural mechanism; competing technical concerns and the counterfactual merge outcome remain unresolved.')

claim('E05','C1','The contemporaneous guide specifies ACK with the top topic-branch commit followed by an account of the review.','supported',[('doc_before','starting with `ACK BRANCH_COMMIT`, where `BRANCH_COMMIT` is the top of the\ntopic branch. The review is followed by a description of how the reviewer did\nthe review.')],'A documented convention does not establish its enforcement in every review.')
claim('E05','C2','practicalswift asks paymog to identify the reviewed version by adding its hash after ACK.','supported',[('comments:1',"Don't forget to include the commit hash after your ACK to specify which version of the PR you are ACK:ing")],'Local review coordination is explicit; no sanction is stated.')
claim('E05','C3','paymog acknowledges the reminder and supplies a hash-specific ACK in a later comment.','supported',[('comments:2','@practicalswift got it. Thanks for the patience.'),('comments:2','ACK 6338c0203416a5f86e9422b6cd479da8af277f2f')],'The separate response supports local uptake. No population compliance rate or durable internalized belief follows.')
claim('E05','C4','The body describes a software precondition, which supplies no institutional duty by itself.','supported',[('body','requires an initialized `secp256k1_context_verify`.'),('body','The fuzzing harness did not fulfil that pre-condition prior to this commit')],'Technical requires should not be converted to an institutional obligation without a separate governance claim.')

claim('E06','C1','The author locally distinguishes a hash-specific code ACK from a concept ACK.','supported',[('comments:5',"If you agree with the changes, please add the latest hash after your ack, otherwise it's just a concept ack.")],'This combines a request and a classification claim; it does not make the author a unilateral rule maker.')
claim('E06','C2','The stored bot table classifies purpleKarrot as stale and laanwj as ACK.','supported',[('comments:0','| ACK | [laanwj]'),('comments:0','| Stale ACK | [purpleKarrot]')],'Mutable table contents have no reliable event time from their original creation timestamp.')
claim('E06','C3','The merge message credits laanwj for the top commit and does not list purpleKarrot there.','supported',[('merge_message','ACKs for top commit:'),('merge_message','laanwj:'),('comments:0','| Stale ACK | [purpleKarrot]')],'Absence was checked against the full commit message. Attribution does not measure all influence on the contribution.')
claim('E06','C4','Stale classification proves a reviewer was punished or excluded from deliberation.','unresolved',[('comments:0','| Stale ACK | [purpleKarrot]'),('comments:5','Thanks for the review and the C++17 suggestion @purpleKarrot.')],'Version-specific accounting and acknowledged input are a plausible alternative to punishment.')

claim('E07','C1','A participant reports incorrect review classification and quotes an earlier table with vicjuma under Concept ACK.','supported',[('comments:3',"I think the @DrahtBot hasn't properly counted @vicjuma's ACK..."),('comments:3','| Concept ACK   | [vicjuma]')],'This is a reported earlier state preserved by quotation, not an independently timestamped bot snapshot.')
