claim('E10','C1','The author presents the minimal MAINTAINERS proposal as descriptive documentation of existing practice.','attributed',[('body','purely descriptive of the current role of maintainership')],'The assertion of descriptiveness is an object of analysis, not proof every proposed sentence is true.')
claim('E10','C2','Focus areas are debated as mutable descriptions; the author explicitly denies that they are enforced rules.','supported',[('review_comments:4','The focus area is something that is entrusted to the maintainer to decide for themselves.'),('review_comments:5','these are not enforced rules, just documentation.')],'The local exchange weighs against reading listed areas as binding and exclusive jurisdiction.')
claim('E10','C3','The author closes the unmerged proposal and leaves it available for others.','supported',[('comments:2',"doesn't seem like there is desire to improve documentation here, closing / up for grabs."),('comments:3','Please mark up for grabs, thanks'),('outcome','"recorded_merged": false')],'Author withdrawal is not a project-wide constitutional vote.')
